#!/usr/bin/env bash
# flock-bench: the binary-census transition unit on Flock-CUDA (RTX 5090).
# Patches cuda-ghash/prove_ffi.cu with `flock_cuda_prove_host` (same prover; the witness is uploaded
# from the host instead of generated by the BLAKE3 kernel; n_blocks_log = m - k_log instead of m - 14),
# and generates tests/gpu_unit.rs from tests/gpu_roundtrip.rs (same parse + Rust verify_ligerito).
# env: UNITS="ampere_bf16:13,17,19 ada_e4m3:12,16,18"  REPS=3  BUILD_ONLY=0
set -uxo pipefail
W=/workspace/flock-bench; F=$W/flock; OUT=$W/out/gpuunit-$(date -u +%H%MZ); mkdir -p $OUT
IN="$RESEARCH_RUN_DIR/inputs"
source $HOME/.cargo/env
export PATH=/usr/local/cuda-13.3/bin:$PATH NVCC=/usr/local/cuda-13.3/bin/nvcc
cd $F
P=crates/flock-prover
cp $IN/verity_unit.rs $P/src/r1cs_hashes/verity_unit.rs
grep -q 'pub mod verity_unit;' $P/src/r1cs_hashes.rs || printf '\npub mod verity_unit;\n' >> $P/src/r1cs_hashes.rs
python3 - <<'EOF'
import re
p = "cuda-ghash/prove_ffi.cu"
s = open(p).read()
if "flock_cuda_prove_host" not in s:
    sig = "int flock_cuda_prove_blake3(const FlockCudaProveParams* P, uint8_t** out, size_t* out_len) {"
    assert s.count(sig) == 1
    s = s.replace(sig, "static int prove_impl(const FlockCudaProveParams* P, uint8_t** out, size_t* out_len,\n"
                  "                      const F128* hz, const F128* ha, const F128* hb, const uint8_t* hzl) {")
    old = "    const int n_blocks_log = m - 14;"
    assert s.count(old) == 1
    s = s.replace(old, "    const int n_blocks_log = m - k_log;")
    blk = "    {\n        uint32_t *d_cv, *d_m, *d_blen, *d_flags; b3u64* d_ctr;"
    assert s.count(blk) == 1, s.count(blk)
    up = ("    if (hz) {\n"
          "        auto tu0 = std::chrono::steady_clock::now();\n"
          "        CK(cudaMemcpy(df, hz, len * sizeof(F128), cudaMemcpyHostToDevice));\n"
          "        CK(cudaMemcpy(d_a, ha, len * sizeof(F128), cudaMemcpyHostToDevice));\n"
          "        CK(cudaMemcpy(d_b, hb, len * sizeof(F128), cudaMemcpyHostToDevice));\n"
          "        CK(cudaMemcpy(d_zlin, hzl, (size_t)len * 16, cudaMemcpyHostToDevice));\n"
          "        CK(cudaDeviceSynchronize());\n"
          "        printf(\"FFI: host witness upload %.4f s (%.3f GB)\\n\", std::chrono::duration<double>(std::chrono::steady_clock::now() - tu0).count(), 4.0 * (double)len * 16 / 1e9);\n"
          "    } else {\n        uint32_t *d_cv, *d_m, *d_blen, *d_flags; b3u64* d_ctr;")
    s = s.replace(blk, up)
    s = s.replace("#include <cstdio>\n", "#include <cstdio>\n#include <chrono>\n", 1)
    end = '} // extern "C"'
    assert s.count(end) == 1
    s = s.replace(end,
        "int flock_cuda_prove_blake3(const FlockCudaProveParams* P, uint8_t** out, size_t* out_len) {\n"
        "    return prove_impl(P, out, out_len, nullptr, nullptr, nullptr, nullptr);\n}\n"
        "int flock_cuda_prove_host(const FlockCudaProveParams* P, const F128* z, const F128* a, const F128* b,\n"
        "                          const uint8_t* zl, uint8_t** out, size_t* out_len) {\n"
        "    return prove_impl(P, out, out_len, z, a, b, zl);\n}\n" + end)
    open(p, "w").write(s)
    print("patched prove_ffi.cu")

t = open("crates/flock-cuda-ffi/tests/gpu_roundtrip.rs").read()
a = "    let r1cs = build_block_r1cs(n_blocks_log);"
assert t.count(a) == 1
t = t.replace(a, "    let net = unit_net();\n    let r1cs = net.block_r1cs(n_blocks_log);\n"
                 "    let tw = Instant::now();\n    let (hz, ha, hb, hzl) = net.witness_row_major(n_blocks_log);\n"
                 "    println!(\"VWIT host_witness_s={:.4}\", tw.elapsed().as_secs_f64());")
c = "unsafe { flock_cuda_prove_blake3(&params, &mut out, &mut out_len) }"
assert t.count(c) == 1
t = t.replace(c, "unsafe { flock_cuda_prove_host(&params, hz.as_ptr(), ha.as_ptr(), hb.as_ptr(), hzl.as_ptr(), &mut out, &mut out_len) }")
d = "    fn flock_cuda_free(p: *mut u8);"
assert t.count(d) == 1
t = t.replace(d, d + "\n    fn flock_cuda_prove_host(p: *const ProveParams, z: *const F128, a: *const F128, b: *const F128,\n"
                 "        zl: *const u8, out: *mut *mut u8, out_len: *mut usize) -> i32;")
i = t.index("#[test]\n#[ignore] // needs an sm_120 GPU; run explicitly with --ignored\nfn gpu_roundtrip_m22")
t = t[:i]
t += '''
use flock_prover::r1cs_hashes::verity_unit::Netlist;
static UNIT_NET: OnceLock<Netlist> = OnceLock::new();
fn unit_net() -> &'static Netlist {
    UNIT_NET.get_or_init(|| {
        let mut net = Netlist::load(&std::env::var("VU_NETLIST").expect("VU_NETLIST"));
        assert_eq!(net.self_check(), 0, "netlist self-check");
        if std::env::var("VU_TAMPER_W").is_ok_and(|s| s == "1") {
            // one vector with operand x[0] exponent all ones: its finiteness assertion row is violated
            let e4m3 = std::env::var("VU_NAME").unwrap_or_default().contains("e4m3");
            let mut v = net.vectors[0].clone();
            for i in if e4m3 { 0..7 } else { 7..15 } {
                v.0[i >> 3] |= 1 << (i & 7);
            }
            net.vectors.push(v);
            println!("VTAMPER witness: 1 invalid vector of {}", net.vectors.len());
        }
        net
    })
}
'''
for nbl in (12, 13, 16, 17, 18, 19):
    t += f"\n#[test]\n#[ignore]\nfn gpu_unit_nbl{nbl}() {{\n    roundtrip::<{nbl}, false>();\n}}\n"
t += "\n#[test]\n#[ignore]\nfn gpu_unit_nbl13_tamper() {\n    roundtrip::<13, true>();\n}\n"
open("crates/flock-cuda-ffi/tests/gpu_unit.rs", "w").write(t)
print("wrote tests/gpu_unit.rs")
EOF
for pipe in ampere_bf16 ada_e4m3 hopper_bf16 hopper_e4m3; do
  (cd $IN && python3 export_unit.py $pipe $OUT/net-$pipe.txt 64) | tee -a $OUT/export.txt
done
cargo test -p flock-cuda-ffi --release --features gpu --test gpu_unit --no-run > $OUT/build.txt 2>&1
rc=$?; tail -25 $OUT/build.txt; [ $rc = 0 ] || { cp -r $OUT "$RESEARCH_RUN_DIR/out"; exit 1; }
[ "${BUILD_ONLY:-0}" = 1 ] && { cp -r $OUT "$RESEARCH_RUN_DIR/out"; exit 0; }
nvidia-smi --query-gpu=name,driver_version,memory.total,clocks.max.sm --format=csv | tee $OUT/gpu.txt
run() {  # name nbl tag [env...]
  local pipe=$1 nbl=$2 tag=$3; shift 3
  while pgrep -f "[p]rove_phase_bench" >/dev/null; do sleep 10; done
  env "$@" VU_NETLIST=$OUT/net-$pipe.txt VU_NAME=$pipe /usr/bin/time -v \
    cargo test -p flock-cuda-ffi --release --features gpu --test gpu_unit -- --ignored --nocapture --exact $tag \
    > $OUT/$pipe-$tag-${REP:-0}.txt 2>&1
  echo "rc=$? $pipe $tag"; grep -E "VWIT|FFI: host|GPU proof verified|VSIZE|rejected|panicked|test result|Maximum resident" $OUT/$pipe-$tag-${REP:-0}.txt
}
# controls first: proof tamper (2 corrupted proofs rejected) and witness tamper (must be rejected)
REP=0 run ampere_bf16 13 gpu_unit_nbl13_tamper
REP=w run ampere_bf16 13 gpu_unit_nbl13 VU_TAMPER_W=1
UNITS=${UNITS:-"ampere_bf16:13,17,19 ada_e4m3:12,16,18"}
for rep in $(seq 1 ${REPS:-3}); do
  for s in $UNITS; do
    IFS=: read pipe nbls <<< "$s"
    for nbl in ${nbls//,/ }; do REP=$rep run $pipe $nbl gpu_unit_nbl$nbl; done
  done
done
cp -r $OUT "$RESEARCH_RUN_DIR/out" 2>/dev/null || true
